import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Configuration | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/guide/configuration"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/configuration"}]]},"headers":[],"relativePath":"catter/guide/configuration.md","filePath":"en/catter/guide/configuration.md","lastUpdated":1793214814000}'),r={name:"catter/guide/configuration.md"};function n(i,e,c,s,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><h2 id="catter-cli" tabindex="-1">catter CLI <a class="header-anchor" href="#catter-cli" aria-label="Permalink to &quot;catter CLI&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter &lt;command&gt; [options] -- &lt;build-command&gt;</span></span></code></pre></div><p>Every run names a command, and its options come after it. <code>catter --help</code> lists the commands, and <code>catter &lt;command&gt; --help</code> shows the options of one. Without a command, catter lists the commands and exits with an error.</p><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>compile-commands</code></td><td>Generate a <code>compile_commands.json</code> file from captured compiler commands. See <a href="./../features/compilation-database">Compilation Database</a>.</td></tr><tr><td><code>tree</code></td><td>Render captured commands as a command tree. See <a href="./../features/command-tree">Command Tree</a>.</td></tr><tr><td><code>targets</code></td><td>Render captured build targets as a flat target forest. See <a href="./../features/target-tree">Target Tree</a>.</td></tr><tr><td><code>profile</code></td><td>Write the timeline of the build&#39;s commands as a trace for Perfetto. See <a href="./../features/build-profiling">Build Profiling</a>.</td></tr><tr><td><code>explain</code></td><td>Print how catter analyzes the command after <code>--</code>, without running it. See <a href="./../features/explain">Explain</a>.</td></tr><tr><td><code>run</code></td><td>Run the build with handlers alone, which decide on and observe its commands. See <a href="./../scripting/handlers">Handlers</a>.</td></tr></tbody></table><p><code>compile-commands</code>, <code>tree</code>, <code>targets</code> and <code>profile</code> each run a built-in on the build, together with the <a href="./../scripting/handlers">handlers</a> the command line names, if any. <code>run</code> runs the handlers alone, and needs at least one.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p><code>compile-commands</code>, <code>tree</code>, <code>targets</code>, <code>profile</code> and <code>run</code> take these options besides their own:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>-C, --directory &lt;path&gt;</code></td><td>The directory the command runs in.</td><td>Current directory</td></tr><tr><td><code>--capture &lt;backend&gt;</code></td><td>How the build&#39;s commands are captured: <code>hook</code>, <code>wrapper</code>, <code>eslogger</code> on macOS, or <code>ptrace</code> on Linux. See <a href="./../design/capture-backends">Capture backends</a>.</td><td><code>hook</code></td></tr><tr><td><code>--from &lt;file&gt;</code></td><td>Replay the build recorded in this file instead of running one.</td><td></td></tr><tr><td><code>--handler &lt;command&gt;</code></td><td>Start a handler, which decides or observes the build&#39;s commands over its stdin and stdout; may be given more than once.</td><td></td></tr><tr><td><code>--connect &lt;host:port&gt;</code></td><td>Connect to a handler listening at the address, on this machine unless <code>--allow-remote</code> is given; may be given more than once.</td><td></td></tr><tr><td><code>--allow-remote</code></td><td>Let <code>--connect</code> reach a handler on another machine.</td><td></td></tr><tr><td><code>--handler-timeout &lt;seconds&gt;</code></td><td>How long catter waits for a handler to answer, and to exit once the session is over; <code>0</code> waits as long as it takes.</td><td><code>60</code></td></tr></tbody></table><p><code>--from</code> takes the place of the build command after <code>--</code>: a run gives one or the other. A relative path is from the <code>-C</code> directory. A recorded build is not captured: <code>--from</code> takes no <code>--capture</code>.</p><p><code>explain</code> takes <code>-C</code> too, and the command to analyze after <code>--</code>.</p><h3 id="exit-status" tabindex="-1">Exit status <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status&quot;">​</a></h3><p>catter ends as the build did: with the build&#39;s exit code, or, when a signal ended the build, by the same signal. A replayed build ends with the exit code its file records. When catter itself fails, as when the command line is wrong, a handler aborts the build or the compilation database or the trace cannot be written, catter prints why and exits with 1.</p><p>Stopping catter stops the build: a SIGTERM, SIGINT or SIGHUP sent to catter goes on to the build command, which ends as it would if it were sent to it, and catter then ends as the build did. A build command ends with catter when catter is killed, but under <code>eslogger</code>.</p><h3 id="data-directory" tabindex="-1">Data directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data directory&quot;">​</a></h3><p>catter keeps its logs and the socket of each running session in <code>$HOME/.catter</code> (Linux, macOS) or <code>%LOCALAPPDATA%\\catter</code> (Windows). The <code>CATTER_HOME</code> environment variable, when set, names another directory, by an absolute path. On Linux and macOS, what the build&#39;s processes log goes to the directory of their session, whatever <code>HOME</code> or <code>CATTER_HOME</code> a build step gives them.</p><h2 id="catter-proxy-cli" tabindex="-1">catter-proxy CLI <a class="header-anchor" href="#catter-proxy-cli" aria-label="Permalink to &quot;catter-proxy CLI&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>catter-proxy</code> is an internal component of catter. It is invoked automatically by catter and is not intended for direct use.</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter-proxy &lt;program&gt; &lt;argv&gt;...</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;program&gt;</code></td><td>The program to run, as the hook found it</td></tr><tr><td><code>&lt;argv&gt;</code></td><td>The program&#39;s arguments, the program&#39;s name first</td></tr></tbody></table><p>It finds the session it reports the command to in its environment, in the variables below.</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>These variables are set automatically by catter at runtime. They are documented here for reference; you should not need to set them manually.</p><h3 id="unix-linux-macos" tabindex="-1">Unix (Linux / macOS) <a class="header-anchor" href="#unix-linux-macos" aria-label="Permalink to &quot;Unix (Linux / macOS)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>__key_catter_proxy_path_v1</code></td><td>Path to the <code>catter-proxy</code> executable</td></tr><tr><td><code>__key_catter_command_id_v1</code></td><td>IPC command identifier</td></tr><tr><td><code>__key_catter_ipc_v1</code></td><td>The pipe of the catter session</td></tr><tr><td><code>__key_catter_decided_v1</code> (Linux)</td><td>The exec <code>catter-proxy</code> started the program with</td></tr><tr><td><code>LD_PRELOAD</code> (Linux)</td><td>Injects the catter hook shared library</td></tr><tr><td><code>DYLD_INSERT_LIBRARIES</code> (macOS)</td><td>Injects the catter hook shared library</td></tr></tbody></table><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>catter sets none: it gives the hook in each process of the build its session directly, and the build&#39;s environment stays as the build made it.</p>',28)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
